{"data": {"id": "solana_DtcicPCKTKeAh7TDEzTym3hXeoHAoMiBdYJhMYxZpump", "type": "token", "attributes": {"address": "DtcicPCKTKeAh7TDEzTym3hXeoHAoMiBdYJhMYxZpump", "name": "Cartoon Money", "symbol": "CBUCKS", "decimals": 6, "image_url": "https://coin-images.coingecko.com/coins/images/102179502/large/678EE431-2780-4460-84CE-2DA090A974B6_%281%29.jpeg?1791957341", "image": {"thumb": "https://coin-images.coingecko.com/coins/images/102179502/thumb/678EE431-2780-4460-84CE-2DA090A974B6_%281%29.jpeg?1791957341", "small": "https://coin-images.coingecko.com/coins/images/102179502/small/678EE431-2780-4460-84CE-2DA090A974B6_%281%29.jpeg?1791957341", "large": "https://coin-images.coingecko.com/coins/images/102179502/large/678EE431-2780-4460-84CE-2DA090A974B6_%281%29.jpeg?1791957341"}, "banner_image_url": null, "coingecko_coin_id": "cartoon-money", "websites": ["https://cartoon-money.com"], "discord_url": null, "farcaster_url": null, "zora_url": null, "telegram_handle": null, "twitter_handle": "cartoonmoney_ai", "description": "Cartoon Money (CBUCKS) is a community-driven entertainment token on the Solana blockchain, built around an interactive, cartoon-style trading game called Coinmoonkitcap. The project mixes the humour and culture of crypto with a playful, game-like experience. People can learn how crypto markets behave, have fun with friends, and take part in a growing online community. Our tagline, "Cartoon Money, A Bigger Tomorrow," sums up the idea: a lighthearted, easy-to-use space where anyone, from total beginners to experienced traders, can enjoy crypto without the stress and complexity of traditional platforms.

At the centre of the project is the Coinmoonkitcap game. It is a parody market that shows about 500 simulated in-game coins, presented in a style that looks like the market tracking sites the crypto community already knows. These in-game coins are not real tokens. They have no value outside the game, cannot be withdrawn, and exist only for play and learning. They let users practise reading charts, following price swings, and managing a pretend portfolio in a safe, cartoon setting, with no real money at risk on those simulated assets. We want to be clear on this point: CBUCKS is the only real token in the Cartoon Money ecosystem. Any in-game coin that uses a familiar name or ticker is part of the parody and is not linked to, endorsed by, or connected with the real project of the same name.

Looking ahead, we plan to keep improving the Coinmoonkitcap experience with new game modes, leaderboards, seasonal events, and more cartoon characters and art. We also want to grow our community on social channels and keep everything transparent through on-chain data. Cartoon Money does not promise financial returns. CBUCKS is a community and entertainment token, and we encourage everyone to take part responsibly and do their own research. The project is about building a fun, welcoming, and lasting corner of the Solana ecosystem where creativity and community come first.", "gt_score": 43.38499758918528, "gt_score_details": {"pool": 48.571, "transaction": 80.0, "creation": 100.0, "info": 100.0, "holders": 60.0}, "gt_verified": true, "categories": ["Pump Fun", "Defi"], "gt_category_ids": ["pump-fun", "defi"], "holders": {"count": 2009, "distribution_percentage": {"top_10": "38.5598", "11_20": "7.3863", "21_40": "8.5692", "rest": "45.4847"}, "last_updated": "2026-11-09T03:21:51Z"}, "mint_authority": null, "freeze_authority": null, "is_honeypot": "unknown", "is_nsfw": false, "developer_address": "3WhAzuGAjnNCJz3kRMog71WGipQvXb2CzaQvjS7mkkXF", "developer_holding_percentage": "47.33", "launchpad_details": {"graduation_percentage": 100.0, "completed": true, "completed_at": "2026-10-06T18:29:54.000Z", "migrated_destination_pool_address": "B4Cp45PGifVM5FAXfh6AeV8QZ3eUNQnqGBw7KuC7MHnB"}}}}
